package io.knowledgebrain.notification;
import java.util.*;import jakarta.servlet.http.Cookie;import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class GroupReviewApiTest {
 GroupReviewStore store=mock(GroupReviewStore.class);GroupReviewAuthority auth=mock(GroupReviewAuthority.class);UUID group=ReviewFixtures.ids.next(),space=ReviewFixtures.ids.next(),actor=ReviewFixtures.ids.next(),id=ReviewFixtures.ids.next();GroupReviewStore.Access a=new GroupReviewStore.Access(group,space,actor,1);GroupReviewController api=new GroupReviewController(store,auth,"https://localhost:8443",new SimpleMeterRegistry());
 @BeforeEach void init(){when(auth.authorize(eq(group),any(),anyString())).thenReturn(a);}
 MockHttpServletRequest r(String method,String body){var r=new MockHttpServletRequest(method,"/api/groups/"+group+"/notification-preference");r.setSecure(true);r.setContentType("application/json");r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.addHeader("If-Match","\"gnp0\"");if(body!=null)r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 @Test void exactBooleanStrongCasAndNoRecipientSpoofing()throws Exception{for(var body:List.of("{}","{\"enabled\":1}","{\"enabled\":true,\"enabled\":false}","{\"enabled\":true} {}","{\"enabled\":true,\"recipientId\":null}"))assertThrows(ResponseStatusException.class,()->api.preferenceChange(group.toString(),r("PUT",body)));var missing=r("PUT","{\"enabled\":true}");missing.removeHeader("If-Match");assertEquals(428,assertThrows(ResponseStatusException.class,()->api.preferenceChange(group.toString(),missing)).getStatusCode().value());for(var tag:List.of("*","W/\"gnp0\"","\"np0\"","\"gnp01\"","\"gnp9223372036854775808\"")){var req=r("PUT","{\"enabled\":true}");req.removeHeader("If-Match");req.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.preferenceChange(group.toString(),req));}verifyNoInteractions(store);}
 @Test void freshAuthorityNoCacheAndDeniedReadsDoNotTouchStore(){when(store.preference(a)).thenReturn(new GroupReviewStore.Preference(group,space,actor,0,1,false,0,null));for(int i=0;i<2;i++){var response=api.preference(group.toString(),r("GET",null));assertEquals("no-store",response.getHeaders().getCacheControl());assertEquals("\"gnp0\"",response.getHeaders().getETag());}verify(auth,times(2)).authorize(eq(group),any(),anyString());reset(store);when(auth.authorize(eq(group),any(),anyString())).thenThrow(new ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND));assertThrows(ResponseStatusException.class,()->api.list(group.toString(),r("GET",null)));verifyNoInteractions(store);}
 @Test void insecureCrossOriginDuplicateCookieUnknownQueryAndReadBodyDenied(){var cross=r("PUT","{}");cross.removeHeader("Origin");assertEquals(403,assertThrows(ResponseStatusException.class,()->api.preferenceChange(group.toString(),cross)).getStatusCode().value());var dup=r("GET",null);dup.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)),new Cookie("__Host-brain_guest","b".repeat(43)));assertEquals(401,assertThrows(ResponseStatusException.class,()->api.preference(group.toString(),dup)).getStatusCode().value());var q=r("GET",null);q.addParameter("recipientId",actor.toString());assertThrows(ResponseStatusException.class,()->api.list(group.toString(),q));assertThrows(ResponseStatusException.class,()->api.preference(group.toString(),r("GET","{}")));var insecure=r("GET",null);insecure.setSecure(false);assertThrows(ResponseStatusException.class,()->api.preference(group.toString(),insecure));verifyNoInteractions(store);}
}
